            pictures = picturePayload,
            syncToDynamic = resolveSyncToDynamicField(syncToDynamic),
            csrf = csrf
        )

        if (response.code == 0) {
            val reply = response.data?.reply
            if (reply != null && reply.rpid > 0L) {
