                modifier = Modifier
                    .fillMaxWidth()
                    .fillMaxHeight(0.7f)
            ) {
                Box(
                    modifier = Modifier
                        .matchParentSize()
                        .layerBackdrop(commentChromeBackdrop)
                        .background(AppSurfaceTokens.background())
                )
                Column(modifier = Modifier.fillMaxSize()) {
                Box(modifier = Modifier.weight(1f).fillMaxWidth()) {
