                                    AndroidRenderEffect.createBlurEffect(
                                        blurFrame.blurRadiusPx,
                                        blurFrame.blurRadiusPx,
                                        Shader.TileMode.CLAMP,
                                    ).asComposeRenderEffect()
                                } else {
                                    null
                                }
                            }
