                                        .fillMaxWidth()
                                        .padding(vertical = AppSpacingTokens.Small),
                                    contentAlignment = Alignment.Center
                                ) {
                                    AdaptiveLoadingIndicator(size = AppSpacingTokens.ExtraLarge)
                                }
                            }
