override suspend fun transform(input: Bitmap, size: Size): Bitmap {
    if (!input.hasAlpha()) return input

    var left = input.width
    var top = input.height
    var right = -1
    var bottom = -1
    for (y in 0 until input.height) {
        for (x in 0 until input.width) {
