                append(" · $displayLocation")
            }
        }
    }
    val avatarSize = remember { resolveSubReplyDetailAvatarSizeDp().dp }
    val nameColor = resolveUpNameColor(
        vipStatus = item.member.vip?.vipStatus ?: 0,
