internal fun resolveSubReplyRemoteTotalCount(
    data: ReplyData,
    rootReply: ReplyItem? = null
): Int {
    // 不同接口会把分页窗口大小也写进 page.count；不能把单页数量当总数。
    // 取所有可用声明中的最大值，避免“显示还有 N 条，详情却在首屏结束”。
    return listOf(
        data.page.count,
        data.root?.rcount ?: 0,
        data.root?.count ?: 0,
        data.cursor.allCount,
        rootReply?.rcount ?: 0,
        rootReply?.count ?: 0,
        data.page.acount
    ).filter { it > 0 }.maxOrNull() ?: 0
}

